gFB(){return"2\u20139 giocatori"},
gFD(){return"Note"},
gFG(){return"Rake / Commissioni"},
gFs(){return"Piazzamento"},
gFL(){return"Iscritti totali"},
gFJ(){return"Qualit\xe0 tavolo (1\u20135)"},
gqO(){return"-- Non nel file --"},
gFP(){return"Data mancante"},
FO(a){return'Data non riconosciuta: "'+a+'"'},
FN(a){return'Buy-in non valido: "'+a+'"'},
gFQ(){return"Nessuna colonna risultato: profitto registrato a $0"},
Gu(a,b){var s=null
return A.ap(a,s,this.a,s,"1 sessione cash ha bui",""+a+" sessioni cash hanno bui",s,s)+' non leggibili per BB/100 (es. "'+b+'"): verranno importate comunque, ma non conteranno per BB/100.'},
gFY(){return"Nessuna colonna risultato mappata"},
gFX(){return"Non hai mappato Cash-out, Premio vinto o Profitto.\n\nTutte le sessioni importate avranno profitto $0.\n\nImporti comunque?"},
gFM(){return"Indietro"},
gFe(){return"Importa comunque"},
